  * At most ``max_concurrent`` task coroutines run at any moment.
  * On Ctrl-C (SIGINT) or outer cancellation, every started task is cancelled
    and then *awaited*, so ``finally`` / ``except CancelledError`` cleanup
    blocks (including ones that themselves await) run to completion before
    ``run_tasks`` propagates KeyboardInterrupt / CancelledError.
  * If tasks raise, the remaining tasks still run; the first exception is
    re-raised afterwards.
"""

from __future__ import annotations

import asyncio
import signal
import threading
from typing import Awaitable, Callable, Iterable, List, Optional

__all__ = ["run_tasks"]

# Bound on how many times a repeated cancellation may interrupt the drain
# phase before we re-cancel stragglers; prevents an unkillable hang.
_MAX_DRAIN_RETRIES = 64


async def _drain(children: List["asyncio.Future[None]"]) -> None:
    """Wait for tasks to finish, surviving cancellations aimed at *us*."""
    retries = 0
    while True:
        alive = [t for t in children if not t.done()]
        if not alive:
            return
        try:
            # shield: a CancelledError delivered to this coroutine must not
            # abort the wait, or cleanup code would be left unfinished.
            await asyncio.shield(asyncio.gather(*alive, return_exceptions=True))
        except asyncio.CancelledError:
            retries += 1
            if retries >= _MAX_DRAIN_RETRIES:
                for t in alive:
                    t.cancel()
                if retries >= 2 * _MAX_DRAIN_RETRIES:
                    raise
            continue


def _first_error(children: List["asyncio.Future[None]"]) -> Optional[BaseException]:
    for t in children:
        if t.done() and not t.cancelled():
            exc = t.exception()
            if exc is not None:
                return exc
    return None


