        raise TypeError("max_concurrent must be an int")
    if max_concurrent < 1:
        raise ValueError("max_concurrent must be >= 1")

    task_list = list(tasks)
    if not task_list:
        return

    loop = asyncio.get_event_loop()
    semaphore = asyncio.Semaphore(max_concurrent)
    interrupted = False

    async def worker(make_awaitable: Callable[[], Awaitable[None]]) -> None:
        async with semaphore:
            await make_awaitable()

    children: List["asyncio.Future[None]"] = [
        asyncio.ensure_future(worker(fn)) for fn in task_list
