    def on_sigint(*_args: object) -> None:
        nonlocal interrupted
        interrupted = True
        for child in children:
            child.cancel()

    # Convert Ctrl-C into cancellation of the child tasks so their cleanup
    # runs inside the event loop instead of the loop being torn down.
